def find_words(board: list[list[str]], words: list[str]) -> list[str]:
    m, n = len(board), len(board[0])
    found = set()
    def dfs(r, c, word, idx, visited):
        if idx == len(word):
            return True
        if r < 0 or r >= m or c < 0 or c >= n or (r, c) in visited or board[r][c] != word[idx]:
            return False
        visited.add((r, c))
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if dfs(r + dr, c + dc, word, idx + 1, visited):
                visited.remove((r, c))
                return True
        visited.remove((r, c))
        return False
    for word in words:
        word_found = False
        for r in range(m):
            if word_found:
                break
            for c in range(n):
                if board[r][c] == word[0]:
                    if dfs(r, c, word, 0, set()):
                        found.add(word)
                        word_found = True
                        break
    return sorted(list(found))
